class Solution:
    def countNumbersWithUniqueDigits(self, n: int) -> int:
        def visit(depth, used):
            if depth == min(n, 10):
                return 0
            total = 0
            for digit in range(10):
                if depth == 0 and digit == 0:
                    continue
                if not used & (1 << digit):
                    total += 1 + visit(depth + 1, used | (1 << digit))
            return total
        return 1 + visit(0, 0)
